// GENERATED by script/spec.ts from cell.json — do not edit.

/// The cell, and the sizes an object places at.
///
/// CELL_SHAMT is the cell<->u relation: 1 cell = 2^CELL_SHAMT u. At 0 they
/// are the same unit; at -1, 1u is 2 cells. Everything below is derived from
/// it rather than written out, so changing it here rescales the ladder, the
/// page and chunk spans, and the object layout together.
///
/// OBJECT_SIZES is grid-aligned steps down from one terrain cell. The largest
/// is U_PER_CELL because that is the terrain's own cell size — an object that
/// size lines up 1:1 with a cell — and the finer tiers are what the object
/// paint writes as sub-cell voxels within the volume's dense field.
///
/// TIERS is 4 deliberately, not 3. When CELL_SHAMT changed U_PER_CELL from
/// 0.5u to 1u, sliding a fixed count of tiers down from it would have
/// silently dropped the finest one (0.125u) that building at sub-block
/// detail already depended on, instead of gaining a coarser option to match
/// the new cell size. One more halving keeps every size that already worked.
pub const CELL_SHAMT: i32 = 0;

/// `2^CELL_SHAMT`.
pub const U_PER_CELL: f64 = 1.0;

/// U_PER_CELL and its halvings, coarsest first.
pub const OBJECT_SIZES: [f64; 4] = [1.0, 0.5, 0.25, 0.125];

/// One of OBJECT_SCALE_EXPONENTS: tier `i` is `2^exp` of a cell.
pub type ObjectScaleExponent = i32;
pub const OBJECT_SCALE_EXPONENTS: [ObjectScaleExponent; 4] = [0, -1, -2, -3];
